from typing import Any


class ConfigError(Exception):
    """Raised when a configuration value cannot be coerced or an env var has no default."""
    pass


def _deep_merge(base: dict, override: dict) -> dict:
    result = dict(base)
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = _deep_merge(result[k], v)
        else:
            result[k] = v
    return result


def _coerce(value: str, expected_type: type) -> Any:
    if expected_type is str:
        return value
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "yes", "1"):
            return True
        if lower in ("false", "no", "0"):
            return False
        raise ConfigError(f"Cannot coerce '{value}' to bool")
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f"Cannot coerce '{value}' to int")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f"Cannot coerce '{value}' to float")
    raise ConfigError(f"Unsupported type {expected_type}")


