import os
import tempfile
import pytest
from envcfg import ConfigError, load, _deep_merge, _coerce, _build_env_keys, _flatten


def test_deep_merge_simple():
    base = {"a": 1, "b": 2}
    override = {"b": 3, "c": 4}
    assert _deep_merge(base, override) == {"a": 1, "b": 3, "c": 4}


def test_deep_merge_nested():
    base = {"x": {"a": 1, "b": 2}}
    override = {"x": {"b": 3, "c": 4}}
    assert _deep_merge(base, override) == {"x": {"a": 1, "b": 3, "c": 4}}


def test_deep_merge_no_override():
    base = {"a": 1, "b": 2}
    override = {}
    assert _deep_merge(base, override) == {"a": 1, "b": 2}


def test_coerce_int_valid():
    assert _coerce("42", int) == 42
    assert _coerce("-7", int) == -7


def test_coerce_int_invalid():
    with pytest.raises(ConfigError):
        _coerce("abc", int)


def test_coerce_float_valid():
    assert _coerce("3.14", float) == 3.14
    assert _coerce(".5", float) == 0.5
    assert _coerce("1e3", float) == 1000.0


def test_coerce_float_invalid():
    with pytest.raises(ConfigError):
        _coerce("abc", float)


def test_coerce_bool_valid():
    assert _coerce("true", bool) is True
    assert _coerce("false", bool) is False
    assert _coerce("yes", bool) is True
    assert _coerce("no", bool) is False
    assert _coerce("1", bool) is True
    assert _coerce("0", bool) is False


def test_coerce_bool_invalid():
    with pytest.raises(ConfigError):
        _coerce("maybe", bool)


def test_coerce_str():
    assert _coerce("hello", str) == "hello"


def test_coerce_empty_str():
    assert _coerce("", str) == ""


